// Marina M5 W3: the build-time catalog generator carries a package with modules. The fixture
// catalog (tests/support/fixtures/plugins/modules-route) is generated by the real generator at
// build time; this checks that its entry holds the source image and decodes, with no Lua, to what
// loading the directory evaluates to.
#include "plugins/boat_plugin_catalog.h"
#include "plugins/boat_plugin_image.h"
#include "plugins/boat_plugin_io.h"
#include "plugins/boat_plugin_load.h"
#include "plugins/boat_plugin_wire.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CHECK(test)                                                                                \
    do {                                                                                           \
        if (!(test)) {                                                                             \
            fprintf(stderr, "%s:%d: %s\n", __FILE__, __LINE__, #test);                             \
            return 1;                                                                              \
        }                                                                                          \
    } while (0)

int main(void)
{
    CHECK(boat_plugin_catalog_count == 1);
    const BoatPluginCatalogEntry *entry = boat_plugin_catalog_find("test.catalog-modules");
    CHECK(entry && entry->wire_size);
    BoatPluginFiles *files = calloc(1, sizeof(*files));
    BoatPluginDecoded *decoded = calloc(1, sizeof(*decoded));
    BoatPluginRevision *revision = calloc(1, sizeof(*revision));
    BoatPluginVoyage *loaded = calloc(1, sizeof(*loaded));
    CHECK(files && decoded && revision && loaded);
    BoatPluginDiagnostic d;
    CHECK(boat_plugin_read("tests/support/fixtures/plugins/modules-route", NULL, files, &d)
        == BOAT_PLUGIN_OK);
    CHECK(boat_plugin_image_is(files->source, files->source_size));
    // The entry carries the image: same bytes as reading the directory, manifest included.
    CHECK(boat_plugin_wire_decode(entry->wire, entry->wire_size, decoded, &d));
    CHECK(decoded->source_size == files->source_size
        && !memcmp(decoded->source, files->source, files->source_size));
    CHECK(
        decoded->parsed.module_count == 2 && !strcmp(decoded->parsed.modules[1], "route.arrival"));
    // The decoded revision equals evaluating the directory (module arrival and all).
    CHECK(boat_plugin_catalog_decode(entry, revision, &d));
    BoatPluginBundle bundle = boat_plugin_bundle(files);
    CHECK(boat_plugin_load_voyage(&bundle, NULL, loaded, &d) == BOAT_PLUGIN_OK);
    CHECK(revision->voyage.digest == loaded->digest && entry->digest == loaded->digest);
    CHECK(revision->voyage.route.arrival_radius == 75 && loaded->route.arrival_radius == 75);
    CHECK(revision->source_size == files->source_size);
    // A wire whose manifest and image disagree is refused at decode, before any use.
    unsigned char *copy = malloc(entry->wire_size);
    CHECK(copy);
    memcpy(copy, entry->wire, entry->wire_size);
    unsigned char *at = copy;
    while (at + 13 <= copy + entry->wire_size && memcmp(at, "route.arrival", 13))
        ++at;
    CHECK(at + 13 <= copy + entry->wire_size);
    at[12] = 'x'; // The first match is the manifest's own text.
    CHECK(!boat_plugin_wire_decode(copy, entry->wire_size, decoded, &d));
    free(copy);
    free(loaded);
    free(revision);
    free(decoded);
    free(files);
    puts("catalog modules: generated entry carries the image and decodes to the loaded voyage");
    return 0;
}
